"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[47466],{73171:e=>{e.exports=JSON.parse('{"functions":[{"name":"teleport","desc":"Mock-aware `TeleportService:Teleport(placeId, player, teleportData)`.","params":[{"name":"placeId","desc":"","lua_type":"number"},{"name":"player","desc":"a real Player or a PlayerMock","lua_type":"Player"},{"name":"teleportData","desc":"","lua_type":"{ [string]: any }?"}],"returns":[],"function_type":"static","source":{"line":102,"path":"src/teleportserviceutils/src/Shared/TeleportServiceUtils.lua"}},{"name":"teleportToPlaceInstance","desc":"Mock-aware `TeleportService:TeleportToPlaceInstance(placeId, instanceId, player, spawnName, teleportData)`,\\nwhich sends a player to one specific running server (e.g. joining a friend).","params":[{"name":"placeId","desc":"","lua_type":"number"},{"name":"instanceId","desc":"the destination job/server id","lua_type":"string"},{"name":"player","desc":"","lua_type":"Player"},{"name":"spawnName","desc":"","lua_type":"string?"},{"name":"teleportData","desc":"","lua_type":"{ [string]: any }?"}],"returns":[],"function_type":"static","source":{"line":123,"path":"src/teleportserviceutils/src/Shared/TeleportServiceUtils.lua"}},{"name":"teleportAsync","desc":"Mock-aware `TeleportService:TeleportAsync(placeId, players, teleportOptions)`. Mock players in the\\nbatch are recorded (with the options\' teleport data) and dropped from the engine call; a batch of\\nonly mocks skips the engine and returns nil. Real players teleport and the TeleportAsyncResult is\\nreturned.","params":[{"name":"placeId","desc":"","lua_type":"number"},{"name":"players","desc":"","lua_type":"{ Player }"},{"name":"teleportOptions","desc":"","lua_type":"TeleportOptions?"}],"returns":[{"desc":"","lua_type":"TeleportAsyncResult?"}],"function_type":"static","source":{"line":157,"path":"src/teleportserviceutils/src/Shared/TeleportServiceUtils.lua"}},{"name":"promiseReserveServer","desc":"Wraps TeleportService:ReserveServer(placeId)","params":[{"name":"placeId","desc":"","lua_type":"number"}],"returns":[{"desc":"Code","lua_type":"Promise<string>"}],"function_type":"static","source":{"line":192,"path":"src/teleportserviceutils/src/Shared/TeleportServiceUtils.lua"}},{"name":"promiseTeleport","desc":"Promise wrapper of [TeleportServiceUtils.teleportAsync] -- so it is mock-aware too, recording mock\\nplayers and resolving without an engine call when the batch is all mocks.","params":[{"name":"placeId","desc":"","lua_type":"number"},{"name":"players","desc":"","lua_type":"{ Player }"},{"name":"teleportOptions","desc":"","lua_type":"TeleportOptions?"}],"returns":[{"desc":"","lua_type":"Promise<TeleportAsyncResult?>"}],"function_type":"static","realm":["Server"],"source":{"line":218,"path":"src/teleportserviceutils/src/Shared/TeleportServiceUtils.lua"}},{"name":"promiseTeleportClient","desc":"A client teleporting itself, retried while the engine refuses the hop.\\n\\nThe promise reports only failure. A teleport that works ends with the player leaving this place, so\\nthe success case never settles -- it stays pending until the client is gone. It rejects with the\\nreason once the attempts are spent, which is the caller\'s cue to take the terminal path: the player\\nis stranded here otherwise. Destroying it (a maid slot cleaning up) stops the retries and rejects\\nwith nothing, so a caller can tell its own teardown from a hop that genuinely failed.\\n\\n```lua\\nmaid._teleport = TeleportServiceUtils.promiseTeleportClient(placeId, Players.LocalPlayer, {\\n\\tteleportData = teleportData,\\n}):Catch(function(err)\\n\\t-- retries spent; the player is going nowhere\\nend)\\n```\\n\\nMock-aware throughout (see [TeleportServiceUtils.teleport]): the hop is recorded on a\\n[PlayerMock] rather than run by the engine, and a refusal is whatever the test injects into the\\n`\\"TeleportService.TeleportInitFailed\\"` lookup.","params":[{"name":"placeId","desc":"","lua_type":"number"},{"name":"player","desc":"the local player, or a PlayerMock standing in for one","lua_type":"Player"},{"name":"config","desc":"","lua_type":"TeleportClientConfig?"}],"returns":[{"desc":"Pending while in flight; rejects with the reason when the attempts are spent.","lua_type":"Promise<()>"}],"function_type":"static","realm":["Client"],"source":{"line":270,"path":"src/teleportserviceutils/src/Shared/TeleportServiceUtils.lua"}}],"properties":[],"types":[{"name":"MockTeleport","desc":"A teleport recorded against a [PlayerMock] (stored in the `\\"TeleportService.Teleport\\"` lookup domain\\nkeyed by destination placeId). `via` names the TeleportService API the caller reached for.","lua_type":"{ via: string, teleportData: { [string]: any }?, instanceId: string?, spawnName: string? }","source":{"line":45,"path":"src/teleportserviceutils/src/Shared/TeleportServiceUtils.lua"}},{"name":"TeleportClientConfig","desc":"How a client teleport retries when the engine refuses it (see\\n[TeleportServiceUtils.promiseTeleportClient]). Every field is optional; an omitted one takes the\\ndefault, and `maxAttempts = 1` means a single try with no retry at all.","lua_type":"{ teleportData: { [string]: any }?, maxAttempts: number?, retryWait: number? }","source":{"line":60,"path":"src/teleportserviceutils/src/Shared/TeleportServiceUtils.lua"}}],"name":"TeleportServiceUtils","desc":"Utilities for teleporting players, including mock-aware wrappers of the user-facing TeleportService\\nteleport APIs. With a [PlayerMock] (a headless test), each teleport is recorded on the mock -- the\\n`\\"TeleportService.Teleport\\"` lookup domain, keyed by destination placeId -- instead of calling the\\nengine, which rejects a mock and would surface as a `TeleportInitFailed`. A test reads the recorded\\nteleport back to assert the hop and the data carried with it:\\n\\n```lua\\nTeleportServiceUtils.teleport(placeId, mock, { SlotId = \\"abc\\" })\\nlocal hop = PlayerMock.readLookup(mock, \\"TeleportService.Teleport\\", placeId)\\n-- hop.via == \\"Teleport\\", hop.teleportData.SlotId == \\"abc\\"\\n```\\n\\nThe refusal side is mocked the same way: since the engine never sees a mock\'s teleport it can never\\nrefuse one, so [TeleportServiceUtils.promiseTeleportClient] takes its `TeleportInitFailed` from the\\n`\\"TeleportService.TeleportInitFailed\\"` lookup a test writes.","source":{"line":21,"path":"src/teleportserviceutils/src/Shared/TeleportServiceUtils.lua"}}')}}]);